[y, fs] =audioread ("D:\\rythm1.mp3"); %audio faylni import qilish

y=y(:,1); %stereoni monoga o'tkazish

f=5000; %shovqin chastotasi

t = (0:length(y)-1)/fs; %vaqt vektori

x=0.1*(cos(2*pi*f*t)); %shovqin

z=y+x'; %shovqinli signal

subplot (4,1,1)

plot (t,y);

xlabel ('Vaqt "Sekund"');

ylabel ('Amplituda "Volt"');

title ('Signal');

grid on;

subplot (4,1,2)

plot (t,x);

xlabel ('Vaqt "Sekund"');

ylabel ('Amplituda "Volt"');

title ('Shovqin');

grid on;

subplot (4,1,3)

plot (t,z);

xlabel ('Vaqt "Sekund"');

ylabel ('Amplituda "Volt"');

title ('Shovqinli signal');

grid on;

subplot (4,1,4)

plot (t,h);

xlabel ('Vaqt "Sekund"');

ylabel ('Amplituda "Volt"');

title ('Filtrlangan signal');

grid on;

wo = f/(fs/2);             % markaziy chastota (normalizatsiya)

bw = wo/35;                % teshik kengligi

[b,a] = iirnotch(wo, bw);  % notch filtr koeffitsientlari

h = filter(b, a, z);

sound (z, fs); %Audioni eshittirish

audiowrite ('D:\\natija.m4a',h,fs)

