% 1D Raqamli filtrlar (Butterworth past chastotali filtr)
Fs = 1000;
t = 0:1/Fs:1;
f_low = 10;
f_high = 120;
x = sin(2*pi*f_low*t) + 0.6*sin(2*pi*f_high*t);

[b, a] = butter(4, 30 / (Fs/2), 'low');
y = filter(b, a, x);

figure;
subplot(2,1,1); plot(t, x, 'r'); title('Shovqinli signal (10 Hz + 120 Hz)'); grid on;
subplot(2,1,2); plot(t, y, 'b'); title('Filtrlangan toza signal (10 Hz)'); grid on;
